import inspect
from functools import wraps
from collections import OrderedDict
from taf.ul.ettf.typed.custom_types import CustomType, BaseType, WrappedData
from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils import exception_causes


class ExpectedReturnTypeError(LibraryError):
    def __init__(self, function, expected_type, result_type):
        error_message = \
            '{function} should return value of type {expected_type}. Expected :{expected_type}, got: {result_type}'.format(
                function=function.__name__,
                expected_type=expected_type,
                result_type=result_type)
        super(ExpectedReturnTypeError, self).__init__(exception_causes.INVALID_TYPE, error_message)


def align_types(types_wtih_names):
    return {name: type_converter
            if isinstance(type_converter, CustomType) else BaseType(type_converter)
            for name, type_converter in types_wtih_names.items()}


class typed(object):
    def __init__(self, returns=None, **kwargs):
        self.expected_returned_type = returns
        self.args_to_types = align_types(kwargs)

    def __call__(self, func):
        decorator_self = self

        @wraps(func)
        def wrapper(*args, **kwargs):
            args_name = list(OrderedDict.fromkeys(inspect.getfullargspec(func)[0]))
            args_dict = OrderedDict(list(zip(args_name, args)))

            for arg_name, type_def in list(decorator_self.args_to_types.items()):
                type_def.wrapped_data = WrappedData(func, args, kwargs)

                if arg_name in list(args_dict.keys()):
                    arg = args_dict[arg_name]
                    args_dict[arg_name] = type_def(arg)

                elif arg_name in list(kwargs.keys()):
                    arg = kwargs[arg_name]
                    kwargs[arg_name] = type_def(arg)

            result = func(*list(args_dict.values()), **kwargs)
            self._check_result_type(func, result)
            return result
        return wrapper

    def _check_result_type(self, func, result):
        if self.expected_returned_type:
            try:
                if isinstance(self.expected_returned_type, CustomType):
                    self.expected_returned_type.assert_type(result)
                else:
                    assert isinstance(result, self.expected_returned_type)
            except AssertionError:
                raise ExpectedReturnTypeError(func, self.expected_returned_type, type(result))
